<?php require_once __DIR__.'/config.php'; ?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin — Rádio Social Plus Brasil</title><link rel="stylesheet" href="assets/style.css?v=3af6cad"></head><body class="register-page"><main class="register-card"><p class="eyebrow">Painel restrito</p><h1>Votos por período.</h1><form id="adminForm" class="register-form"><div class="two"><label>Login<input name="login" required></label><label>Senha<input name="password" type="password" required></label></div><button class="primary-btn">Entrar no painel →</button></form><div id="adminResult"></div></main><script>document.querySelector('#adminForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const r=await fetch('api/index.php?action=admin',{method:'POST',body:f}).then(x=>x.json());const el=document.querySelector('#adminResult');if(r.error){el.innerHTML='<p class="form-message">'+r.error+'</p>';return}el.innerHTML='<p style="margin-top:25px"><a class="outline-btn" href="api/index.php?action=users.csv&key='+encodeURIComponent(f.get('password'))+'">Baixar usuários em CSV</a></p><h3>Últimos 31 dias</h3>'+r.votes.map(x=>'<p>'+x.day+' — <b>'+x.votes+'</b> votos</p>').join('')};</script></body></html>
